import gzip
import io
import tarfile
import zlib

import pytest

from multipak import alpine
from multipak.metadata import inspect_package, package_kind

PKGINFO = (
    "# Generated by abuild 3.17.0_rc1-r2\n"
    "# using fakeroot version 1.37.2\n"
    "pkgname = demo-viewer\n"
    "pkgver = 0.2.6-r0\n"
    "pkgdesc = Picture   viewer\n"
    "url = https://example.org\n"
    "builddate = 1721917703\n"
    "packager = Builder <builder@example.org>\n"
    "size = 117351\n"
    "arch = x86_64\n"
    "origin = demo-viewer\n"
    "license = GPL-2.0-or-later\n"
    "provides = cmd:demo-viewer=0.2.6-r0\n"
    "depend = so:libX11.so.6\n"
    "depend = so:libc.musl-x86_64.so.1\n"
    "depend = !demo-viewer-legacy\n"
    "depend = desktop-file-utils\n"
    "datahash = ae8ef9eb9318b0317fde5e8a8dce0d469f574f7253cd049a5d7e5e02fac49166\n"
)
PAYLOAD = {
    "usr/bin/demo-viewer": b"\x7fELF fake",
    "usr/share/applications/demo-viewer.desktop": (
        b"[Desktop Entry]\nType=Application\nName=Demo\nExec=demo-viewer %F\n"
    ),
}


def tar_segment(members: dict[str, bytes], *, cut: bool = True) -> bytes:
    """A TAR; abuild cuts the end-of-archive blocks of the signature and control parts."""
    buffer = io.BytesIO()
    archive = tarfile.open(fileobj=buffer, mode="w", format=tarfile.PAX_FORMAT)
    for name, raw in members.items():
        entry = tarfile.TarInfo(name)
        entry.size = len(raw)
        entry.mode = 0o644
        archive.addfile(entry, io.BytesIO(raw))
    end = archive.offset
    archive.close()
    return buffer.getvalue()[:end] if cut else buffer.getvalue()


def make_apk(path, pkginfo=PKGINFO, payload=None, *, signed=True):
    streams = []
    if signed:
        streams.append(
            tar_segment({".SIGN.RSA.builder@example.org-6165ee59.rsa.pub": b"\x00" * 256})
        )
    streams.append(tar_segment({".PKGINFO": pkginfo.encode()}))
    streams.append(tar_segment(PAYLOAD if payload is None else payload, cut=False))
    path.write_bytes(b"".join(gzip.compress(stream) for stream in streams))
    return path


def make_v3(path):
    # apk-tools 3: "ADB" + compression ("d" = deflate), then the database blocks.
    path.write_bytes(b"ADBd" + zlib.compress(b"pckg" + b"\x00" * 64)[2:])
    return path


@pytest.fixture(autouse=True)
def x86_64(monkeypatch):
    monkeypatch.setattr("multipak.metadata.platform.machine", lambda: "x86_64")


def test_reads_a_signed_classic_package(tmp_path):
    path = make_apk(tmp_path / "demo-viewer-0.2.6-r0.apk")
    info = alpine.read_info(path)
    assert info == alpine.Info(
        "demo-viewer",
        "0.2.6-r0",
        "x86_64",
        "Picture viewer",
        "so:libX11.so.6\nso:libc.musl-x86_64.so.1\ndesktop-file-utils",
        True,
        "3.24",
    )
    assert alpine.dependency_lines(info.dependencies) == [
        "libX11.so.6",
        "libc.musl-x86_64.so.1",
        "desktop-file-utils",
    ]


def test_unsigned_package_is_still_alpine(tmp_path):
    path = make_apk(tmp_path / "local.apk", signed=False)
    assert alpine.is_candidate(path, path.read_bytes()[:16])
    assert not alpine.read_info(path).signed


def test_is_detected_before_arch_and_suggests_alpine(tmp_path):
    # Arch's reader would accept this .PKGINFO too.
    path = make_apk(tmp_path / "renamed.pkg.tar.gz")
    assert package_kind(path) == "apk"
    package = inspect_package(path, runner=None)
    assert (package.kind, package.name, package.version) == ("apk", "demo-viewer", "0.2.6-r0")
    assert (package.distro_hint, package.distro_hint_source) == ("alpine-3.24", "metadata")


def test_arch_pkginfo_is_not_taken_for_alpine(tmp_path):
    arch = (
        "pkgname = demo\npkgbase = demo\npkgver = 1-1\narch = x86_64\n"
        "xdata = pkgtype=pkg\norigin = demo\ndatahash = 00\n"
    )
    path = make_apk(tmp_path / "demo.pkg.tar.gz", arch, signed=False)
    assert not alpine.is_candidate(path, path.read_bytes()[:16])


def test_gzip_without_alpine_fields_is_not_a_candidate(tmp_path):
    path = make_apk(tmp_path / "x.tgz", "pkgname = a\npkgver = 1-r0\narch = x86_64\n", signed=False)
    assert not alpine.is_candidate(path, path.read_bytes()[:16])


def test_apk_v3_is_refused_clearly(tmp_path):
    path = make_v3(tmp_path / "demo-1.0-r0.apk")
    with pytest.raises(ValueError, match="apk v3"):
        inspect_package(path, runner=None)


def test_android_app_is_refused_clearly(tmp_path):
    path = tmp_path / "game.apk"
    path.write_bytes(b"PK\x03\x04" + b"\x00" * 64)
    with pytest.raises(ValueError, match="Android"):
        inspect_package(path, runner=None)


@pytest.mark.parametrize(
    ("change", "message"),
    [
        (lambda text: text.replace("pkgname = demo-viewer\n", ""), "pkgname"),
        (lambda text: text + "arch = aarch64\n", "arch"),
        (lambda text: text.replace("demo-viewer\npkgver", "../evil\npkgver"), "name"),
        (lambda text: text.replace("0.2.6-r0\npkgdesc", "$(x)\npkgdesc"), "version"),
        (lambda text: text + "not a field\n", "Invalid Alpine"),
    ],
)
def test_rejects_bad_metadata(tmp_path, change, message):
    path = make_apk(tmp_path / "bad.apk", change(PKGINFO))
    with pytest.raises(ValueError, match=message):
        alpine.read_info(path)


def test_other_architecture_is_refused(tmp_path):
    path = make_apk(tmp_path / "a.apk", PKGINFO.replace("arch = x86_64", "arch = aarch64"))
    with pytest.raises(ValueError, match="aarch64"):
        inspect_package(path, runner=None)


def test_noarch_is_accepted(tmp_path):
    path = make_apk(tmp_path / "a.apk", PKGINFO.replace("arch = x86_64", "arch = noarch"))
    assert inspect_package(path, runner=None).architecture == "noarch"


def test_never_extracts_and_stops_at_the_payload(tmp_path, monkeypatch):
    # Without .PKGINFO before the payload, the reader stops at the first file.
    path = tmp_path / "x.apk"
    path.write_bytes(gzip.compress(tar_segment({"usr/bin/x": b"x", ".PKGINFO": b"pkgname = x"})))
    monkeypatch.setattr(tarfile.TarFile, "extract", lambda *a, **k: pytest.fail("extract"))
    monkeypatch.setattr(tarfile.TarFile, "extractall", lambda *a, **k: pytest.fail("extract"))
    with pytest.raises(ValueError, match=r"\.PKGINFO"):
        alpine.read_info(path)


def test_oversized_pkginfo_is_refused(tmp_path):
    big = PKGINFO + "# " + "x" * (alpine.MAX_METADATA_FILE + 1) + "\n"
    with pytest.raises(ValueError, match="Invalid Alpine"):
        alpine.read_info(make_apk(tmp_path / "big.apk", big))


def test_corrupt_stream_is_reported(tmp_path):
    path = make_apk(tmp_path / "x.apk")
    raw = path.read_bytes()
    path.write_bytes(raw[:40])
    with pytest.raises(ValueError, match="could not be read|does not contain"):
        alpine.read_info(path)


@pytest.mark.parametrize(
    ("value", "release"), [("3.24.3", "3.24"), ("3.24", "3.24"), ("edge", ""), ("", "")]
)
def test_release_version(value, release):
    assert alpine.release_version(value) == release
